/* MUTANT: one refusal broken on purpose. Generated by mut/make.py. */
/* <ov-geomap> - countries and great-circle routes on a flat world.
 *
 * A companion to <ov-tactical> (the same routes under a camera).
 *
 *   <ov-geomap countries source="flights"></ov-geomap>
 *   <ov-geomap countries="…/ov-countries.js" view="-12 25 45 58" naive src="scene.json"></ov-geomap>
 *   map.routes = [{ id, label, from: {lat, lon}, to: {lat, lon}, pos: {lat, lon, at} }];
 *
 * Attributes: view ("west south east north", degrees; default the world from
 * 60 S to 84 N), countries (see ov-geo.js), naive (draw the straight screen
 * line too), fresh (seconds a fix stays fresh, default 60), source, src (a
 * scene file whose fixes state `age` in seconds before now).
 *
 * ⭐ THE FINDING THIS EXISTS FOR: A STRAIGHT LINE ON THE PROJECTION IS NOT THE
 * SHORTEST PATH. Every route is drawn as its great circle. With `naive`, the
 * straight screen line everyone draws is beside it, with its length measured
 * on the ground: LHR to NRT is 9,591 km as flown and 11,437 km along the line.
 *
 * 🔴 AN ARC IS NOT A LIVE TRACK UNLESS SOMETHING MOVED. See ov-geo.js for the
 * states. A route with no fix is a still, dashed plan. The flown part ends at
 * the REPORTED position's foot on the route, and a fix more than 25 km off the
 * route prints how far off it is instead of being drawn on the line. Only a
 * fresh fix that moved gets the ping, and only while it stays fresh.
 *
 * Nothing here ticks. The map redraws when data, attributes or its size
 * change, and on one timer set for the next moment a fix's words change
 * (started after arrival, and not while the map is off screen).
 */

import { define, whenArrived, watchSeen, isSeen } from '../../../src/ov-core.js';
import '../../../src/ov-source.js';
import {
  R, toVec, angle, valid, ll, greatCircle, onRoute, judge, fixWords, nextDue, remember, dated,
  countriesFor, countriesRefusal, onCountries, setCountries, getCountries, decode, placeLabel, fmtKm, esc,
} from '../../../src/ov-geo.js';

const px = (lon) => lon + 180;
const py = (lat) => 90 - lat;
const WORLD = { w: -180, s: -60, e: 180, n: 84 };
const f2 = (n) => n.toFixed(2);

/* A polyline broken where it crosses the antimeridian, instead of a stripe
 * drawn across the whole map. */
function pathOf(points) {
  let d = '', prev = null;
  for (const p of points) {
    if (prev && Math.abs(p.lon - prev.lon) > 180) {
      const east = prev.lon > 0;
      const lon2 = p.lon + (east ? 360 : -360);
      const t = ((east ? 180 : -180) - prev.lon) / (lon2 - prev.lon);
      const lat = prev.lat + t * (p.lat - prev.lat);
      d += `L${f2(px(east ? 180 : -180))} ${f2(py(lat))}M${f2(px(east ? -180 : 180))} ${f2(py(lat))}`;
    }
    d += `${prev ? 'L' : 'M'}${f2(px(p.lon))} ${f2(py(p.lat))}`;
    prev = p;
  }
  return d;
}

const drawn = new WeakMap();

/* Land and borders, in degrees, so the paths do not depend on the map's size
 * and are built once per outline data. */
function countryPaths(data) {
  let p = drawn.get(data);
  if (p) return p;
  const { arcs, rings } = decode(data);
  let land = '';
  for (const ring of rings) {
    // 🔴 Rings that cross the antimeridian (Chukotka, Fiji) jump from x=360
    // to x=0 in the data, which filled a stripe across the map. Each ring is
    // unwrapped into one run and drawn again shifted by 360 where it runs past
    // an edge; the viewBox clips both copies.
    const out = [];
    let lo = Infinity, hi = -Infinity;
    for (const [lon, lat] of ring) {
      let x = px(lon);
      if (out.length) {
        const lx = out[out.length - 1][0];
        while (x - lx > 180) x -= 360;
        while (lx - x > 180) x += 360;
      }
      out.push([x, py(lat)]);
      if (x < lo) lo = x;
      if (x > hi) hi = x;
    }
    const d = (s) => 'M' + out.map(([x, y]) => `${(x + s).toFixed(1)} ${y.toFixed(1)}`).join('L') + 'Z';
    land += d(0) + (lo < 0 ? d(360) : '') + (hi > 360 ? d(-360) : '');
  }
  // Every arc once, so a shared border is not stroked twice, broken where it
  // jumps the antimeridian and along the cut itself, which is not a border.
  let borders = '';
  for (const pts of arcs) {
    pts.forEach(([lon, lat], i) => {
      const join = i && Math.abs(lon - pts[i - 1][0]) < 180 && !(Math.abs(lon) > 179.9 && Math.abs(pts[i - 1][0]) > 179.9);
      borders += `${join ? 'L' : 'M'}${px(lon).toFixed(1)} ${py(lat).toFixed(1)}`;
    });
  }
  p = { land, borders };
  drawn.set(data, p);
  return p;
}

class OvGeomap extends HTMLElement {
  static observedAttributes = ['view', 'countries', 'naive', 'fresh', 'source', 'src'];
  static now = () => Date.now();
  static get countries() { return getCountries(); }
  static set countries(d) { setCountries(d); }

  constructor() {
    super();
    this._memory = { last: new Map(), prev: new Map() };
    this._labels = { slots: new Map(), boxes: [], x0: 0 };
  }

  connectedCallback() {
    this._ro = new ResizeObserver(() => this.paint());
    this._ro.observe(this);
    this._unseen = watchSeen(this, () => this.paint());
    this._uncountries = onCountries(() => this.paint());
    this.bindSource();
    this.load();
    this.paint();
  }

  disconnectedCallback() {
    this._ro?.disconnect();
    this._ro = null;
    this._unseen?.();
    this._uncountries?.();
    if (this.unsub) this.unsub();
    this.unsub = null;
    clearTimeout(this._timer);
    this._unarrive?.();
    this._unarrive = null;
  }

  attributeChangedCallback(name) {
    if (!this._ro) return;
    if (name === 'source') this.bindSource();
    if (name === 'src') this.load();
    this.paint();
  }

  get fresh() {
    const v = Number(this.getAttribute('fresh'));
    return this.hasAttribute('fresh') && v > 0 ? v : 60;
  }

  get routes() { return this._routes; }
  set routes(rows) {
    const list = Array.isArray(rows) ? rows : Array.isArray(rows?.routes) ? rows.routes : [];
    remember(this._memory, list);
    this._routes = list;
    this._heard = true;
    this.paint();
  }

  /* Outline data for this map only; null says "none", which is refused. */
  get countriesData() { return this._countries; }
  set countriesData(d) { this._countries = d; this.paint(); }

  bindSource() {
    if (this.unsub) this.unsub();
    this.unsub = null;
    this._heard = false;
    const name = this.getAttribute('source');
    if (!name || !window.Overscan?.subscribe) return;
    this.unsub = window.Overscan.subscribe(name, (rows) => { this.routes = rows; });
  }

  async load() {
    const src = this.getAttribute('src');
    this._srcFail = null;
    if (!src) return;
    let data;
    try {
      const r = await fetch(src);
      if (!r.ok) throw new Error(String(r.status));
      data = await r.json();
    } catch { data = undefined; }
    if (this.getAttribute('src') !== src) return;
    if (data === undefined) { this._srcFail = src; this.paint(); return; }
    const now = OvGeomap.now();
    const list = Array.isArray(data) ? data : Array.isArray(data?.routes) ? data.routes : [];
    this.routes = list.map((r) => (r && typeof r === 'object' ? { ...r, pos: dated(r.pos, now) } : r));
  }

  view() {
    const raw = this.getAttribute('view');
    if (raw === null) return WORLD;
    const v = raw.trim().split(/[\s,]+/).map(Number);
    const fine = v.length === 4 && v.every(Number.isFinite)
      && v[0] >= -180 && v[2] <= 180 && v[0] < v[2] && v[1] >= -90 && v[3] <= 90 && v[1] < v[3];
    return fine ? { w: v[0], s: v[1], e: v[2], n: v[3] } : { ...WORLD, bad: raw };
  }

  route(r, now, ctx) {
    if (!r || !valid(r.from) || !valid(r.to)) { ctx.unplaced += 1; return ''; }
    const k = ctx.k;
    const from = ll(r.from), to = ll(r.to);
    const gc = greatCircle(from, to);
    const id = r.id ?? r.label ?? `${from.lat},${from.lon}`;
    const words = [];
    let svg = '';

    // The straight screen line, measured on the ground.
    if (this.hasAttribute('naive')) {
      let lon1 = to.lon;
      if (lon1 - from.lon > 180) lon1 -= 360; else if (from.lon - lon1 > 180) lon1 += 360;
      const line = [];
      let km = 0, prev = toVec(from.lat, from.lon);
      for (let i = 0; i <= 180; i++) {
        const t = i / 180, lat = from.lat + t * (to.lat - from.lat), lon = from.lon + t * (lon1 - from.lon);
        const v = toVec(lat, lon);
        if (i) km += angle(prev, v) * R;
        prev = v;
        line.push({ lat, lon: ((lon + 540) % 360) - 180 });
      }
      svg += `<path class="ov-geomap__naive" d="${pathOf(line)}"/>`;
      words.push(`SCREEN LINE ${fmtKm(km)}, +${fmtKm(km - gc.km)}`);
    }

    const state = judge(r.pos, this._memory.prev.get(id), now, this.fresh);
    let cut = 0, at = from, head = '';
    if (state !== 'plan') {
      at = ll(r.pos);
      const o = onRoute(gc, at);
      cut = Math.round(o.frac * gc.n);
      if (o.xtKm > 25) words.push(`${fmtKm(o.xtKm)} OFF ROUTE`);
      ctx.fixes.push(r.pos);
      head = `<g class="ov-geomap__head" transform="translate(${f2(px(at.lon))} ${f2(py(at.lat))})">`
        + `<circle r="${(4 * k).toFixed(3)}"/>`
        + (state !== 'plan' ? `<circle class="ov-geomap__ping" r="${(4 * k).toFixed(3)}"/>` : '') + '</g>';
    }
    words.push(fixWords(state, r.pos, now));

    svg += `<path class="ov-geomap__route is-ahead" d="${pathOf(gc.points.slice(cut))}"/>`;
    if (cut > 0) svg += `<path class="ov-geomap__route is-flown" d="${pathOf(gc.points.slice(0, cut + 1))}"/>`;
    for (const end of [from, to]) {
      svg += `<rect class="ov-geomap__end" x="${f2(px(end.lon) - 3 * k)}" y="${f2(py(end.lat) - 3 * k)}" width="${(6 * k).toFixed(3)}" height="${(6 * k).toFixed(3)}"/>`;
    }
    svg += head;

    const title = `${esc(r.label ?? '')} ${fmtKm(gc.km)}`.trim();
    const sub = esc(words.join(' · '));
    const spot = placeLabel(ctx.labels, id, px(at.lon), py(at.lat), Math.max(title.length * 1.2, sub.length), k, ctx.width);
    svg += `<text class="ov-geomap__label" style="font-size:${(10 * k).toFixed(3)}px" x="${f2(spot.x)}" y="${f2(spot.y)}"${spot.left ? ' text-anchor="end"' : ''}>`
      + `<tspan>${title}</tspan><tspan class="ov-geomap__sub" x="${f2(spot.x)}" dy="1.2em">${sub}</tspan></text>`;

    ctx.states[state] = (ctx.states[state] || 0) + 1;
    return `<g class="ov-geomap__trip" data-ov-state="${state}" data-ov-id="${esc(id)}">${svg}</g>`;
  }

  paint() {
    if (!this.isConnected || !isSeen(this)) return;
    const now = OvGeomap.now();
    const v = this.view();
    const width = v.e - v.w, height = v.n - v.s;
    const k = width / (this.clientWidth || 720);

    let grid = '';
    for (let lon = -180; lon <= 180; lon += 30) grid += `M${px(lon)} 0V180`;
    for (let lat = -60; lat <= 90; lat += 30) grid += `M0 ${py(lat)}H360`;

    const c = countriesFor(this, this.hasAttribute('countries'), this.getAttribute('countries'));
    const land = c.state === 'ready' ? countryPaths(c.data) : null;
    this._labels.boxes = [];
    this._labels.x0 = px(v.w);
    this._labels.y0 = py(v.n);
    this._labels.height = height;
    const ctx = { k, width, fixes: [], states: {}, unplaced: 0, labels: this._labels };
    const routes = (this._routes || []).map((r) => this.route(r, now, ctx)).join('');

    const key = [];
    const refuse = (s) => key.push(`<b class="ov-geomap__refuse">${s}</b>`);
    const nope = countriesRefusal(c);
    if (nope) refuse(esc(nope));
    if (v.bad !== undefined) refuse(`VIEW UNREADABLE: "${esc(v.bad)}", the world is shown`);
    if (ctx.unplaced) refuse(`${ctx.unplaced} ROUTE${ctx.unplaced > 1 ? 'S' : ''} WITHOUT BOTH ENDS`);
    // A source named and never heard from is NOT an empty sky (ov-map's rule).
    if (this.getAttribute('source') && !this._heard) refuse('NO FEED: nothing received from the source');
    if (this._srcFail) refuse(`SCENE FAILED TO LOAD: ${esc(this._srcFail)}`);
    key.push('<span><i class="is-flown"></i>flown, to the reported fix<i class="is-ahead"></i>great circle ahead</span>');
    if (this.hasAttribute('naive')) key.push('<span><i class="is-naive"></i>straight screen line</span>');
    if (land) key.push('<span class="ov-aside">coastlines 1:110m: nothing nearer a coast than about 11 km can be judged here</span>');

    this.innerHTML =
      `<svg class="ov-geomap__svg" viewBox="${px(v.w)} ${py(v.n)} ${width} ${height}" style="aspect-ratio:${width}/${height}" aria-hidden="true">`
      + `<path class="ov-geomap__grid" d="${grid}"/>`
      + (land ? `<path class="ov-geomap__land" d="${land.land}"/><path class="ov-geomap__border" d="${land.borders}"/>` : '')
      + routes + '</svg>'
      + `<span class="ov-geomap__key">${key.join('')}</span>`;

    const counts = Object.entries(ctx.states).map(([s, n]) => `${n} ${s}`).join(', ');
    this.setAttribute('role', 'img');
    this.setAttribute('aria-label', `map, ${(this._routes || []).length} routes${counts ? `: ${counts}` : ''}`
      + (ctx.unplaced ? `, ${ctx.unplaced} without both ends` : '') + (nope ? `. ${nope}` : '') + '.');
    this.schedule(nextDue(ctx.fixes, now, this.fresh), now);
  }

  schedule(due, now) {
    clearTimeout(this._timer);
    this._timer = null;
    this._unarrive?.();
    this._unarrive = null;
    if (due === null) return;
    // ⚠️ After arrival whenArrived() runs this at once and returns a no-op;
    // keeping that no-op would cancel nothing, so it is kept only before.
    let started = false;
    const off = whenArrived(() => {
      started = true;
      this._timer = setTimeout(() => { this._timer = null; this.paint(); }, Math.max(0, due - now) + 20);
    });
    if (!started) this._unarrive = off;
  }
}

define('ov-geomap', OvGeomap);

export { OvGeomap };
